// =====================================================================
//  ANALYSER LES FLUX — croise le planning du jour, les clés de diffusion
//  et ce que renvoie YouTube pour chaque chaîne.
//  Sortie : un seul élément { flux: [...], cles: [...], videoIds: [...] }
// =====================================================================

// ---------- Réglages ----------
const TZ = 'Europe/Paris';
const AVANT_MIN = 15;     // minutes avant le coup d'envoi : au-delà, l'absence de flux passe en rouge
const DUREE_MIN = { FOOTBALL: 120, BASKET: 120, HANDBALL: 100, RUGBY: 120, TENNIS: 300, AUTRE: 120 };
const SEUIL_APPROX = 0.75;
// Championnats sans clé de diffusion club (flux produits ailleurs) : non suivis
const CHAMPIONNATS_IGNORES = ['LIGUE 3']; // ressemblance minimale entre un nom d'équipe et une clé (1 = identique)

// Une ligne par chaîne YouTube. "noeud" = suffixe des 3 nœuds HTTP de la chaîne.
// sport = null : la chaîne peut diffuser tous les sports.
const CHAINES = [
  { nom: 'D+ Football Normandie',            sport: 'FOOTBALL', noeud: 'Football Normandie' },
  { nom: 'D+ Football Normandie National',   sport: 'FOOTBALL', noeud: 'Football Normandie National' },
  { nom: 'D+ Basket Normandie',              sport: 'BASKET',   noeud: 'Basket Normandie' },
  { nom: 'D+ Basketball Normandie National', sport: 'BASKET',   noeud: 'Basketball Normandie National' },
  { nom: 'D+ Handball Normandie',            sport: 'HANDBALL', noeud: 'Handball Normandie' },
  { nom: 'D+ Rugby Normandie',               sport: 'RUGBY',    noeud: 'Rugby Normandie' },
  { nom: 'D+ Tennis Normandie',              sport: 'TENNIS',   noeud: 'Tennis Normandie' }
];

// ---------- Outils ----------
const norm = (s) => String(s ?? '').normalize('NFD').replace(/[̀-ͯ]/g, '')
  .toUpperCase().replace(/[^A-Z0-9]+/g, ' ').trim();
const MOTS_VIDES = new Set(['FC', 'AS', 'US', 'SC', 'RC', 'CS', 'ES', 'AC', 'CA', 'SM', 'ST', 'STE', 'CLUB', 'DE', 'DU', 'DES', 'LA', 'LE', 'LES', 'L', 'D', 'ET']);   // (F) reste : il distingue les équipes féminines
const jetons = (s) => new Set(norm(s).split(' ').filter((t) => t && !MOTS_VIDES.has(t)));
function ressemblance(a, b) {
  if (norm(a) === norm(b)) return 1;
  const A = jetons(a), B = jetons(b);
  if (!A.size || !B.size) return 0;
  let n = 0; A.forEach((t) => { if (B.has(t)) n++; });
  return n / (A.size + B.size - n);
}
// « RTMP Stream | Evreux Netreville BB | API » -> « Evreux Netreville BB »
const nomEquipe = (titre) => { const m = String(titre || '').match(/^\s*RTMP Stream\s*\|\s*(.*?)\s*\|\s*API\s*$/i); return m ? m[1] : String(titre || '').trim(); };
function famille(sport) {
  const s = norm(sport);
  if (/FOOT|FUTSAL/.test(s)) return 'FOOTBALL';
  if (/BASKET/.test(s)) return 'BASKET';
  if (/HAND/.test(s)) return 'HANDBALL';
  if (/RUGBY/.test(s)) return 'RUGBY';
  if (/TENNIS|PING/.test(s)) return 'TENNIS';
  return 'AUTRE';
}

// Heure de Paris sans bibliothèque externe
const FMT = new Intl.DateTimeFormat('fr-FR', { timeZone: TZ, year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' });
function paris(date) {
  const p = Object.fromEntries(FMT.formatToParts(date).map((x) => [x.type, x.value]));
  return { y: +p.year, m: +p.month, d: +p.day, H: +p.hour, M: +p.minute };
}
const pad = (n) => String(n).padStart(2, '0');
const jour = (p) => `${pad(p.d)}/${pad(p.m)}/${p.y}`;
const horo = (date) => { const p = paris(date); return `${jour(p)} ${pad(p.H)}:${pad(p.M)}`; };
// « 21/11/2026 » + « 18:30 » (heure de Paris) -> Date
function dateParis(dateTxt, heureTxt) {
  const d = String(dateTxt || '').match(/(\d{1,2})\/(\d{1,2})\/(\d{4})/);
  const h = String(heureTxt || '').match(/(\d{1,2})[:hH](\d{2})/);
  if (!d || !h) return null;
  const guess = Date.UTC(+d[3], +d[2] - 1, +d[1], +h[1], +h[2]);
  const p = paris(new Date(guess));
  const decalage = Date.UTC(p.y, p.m - 1, p.d, p.H, p.M) - guess;   // +1 h ou +2 h
  return new Date(guess - decalage);
}
function lire(nom) {
  try { return $(nom).all().map((i) => i.json); } catch (e) { return null; }   // nœud non exécuté
}
const vide = (o) => !o || !Object.keys(o).length;

// ---------- Données d'entrée ----------
const maintenant = new Date();
const aujourdhui = jour(paris(maintenant));
const MAJ = horo(maintenant);

const planning = (lire('Planning (à venir D+)') || []).filter((r) => !vide(r));
const clesSheet = (lire('Clés de diffusion') || []).filter((r) => r.STREAM_ID);
const precedent = (lire('Flux précédent') || []).filter((r) => !vide(r) && r.DATE === aujourdhui);
const prevParMatch = new Map(precedent.filter((r) => r.ID_MATCH).map((r) => [r.ID_MATCH, r]));
const prevParCle = new Map(precedent.filter((r) => !r.ID_MATCH && r.STREAM_ID).map((r) => [r.STREAM_ID, r]));

// ---------- YouTube, chaîne par chaîne ----------
const flux = [];
const streams = new Map();       // id -> { s, chaine }
const lives = [];                // liveBroadcasts (en direct + à venir)
const erreurs = [];

const erreurDe = (rep) => {
  if (!rep || !rep.length) return 'aucune réponse';
  const e = rep.find((r) => r.error);
  if (!e) return '';
  const err = e.error;
  return typeof err === 'string' ? err : (err.message || err.description || JSON.stringify(err)).slice(0, 300);
};

CHAINES.forEach((c) => {
  const rs = lire('YT clés — ' + c.noeud);
  const rd = lire('YT en direct — ' + c.noeud);
  const ra = lire('YT à venir — ' + c.noeud);
  const err = erreurDe(rs);
  if (err) { erreurs.push({ chaine: c.nom, msg: err }); return; }
  rs.forEach((r) => (r.items || []).forEach((s) => streams.set(s.id, { s, chaine: c })));
  if (rs[rs.length - 1].nextPageToken) erreurs.push({ chaine: c.nom, msg: 'Plus de 300 clés de diffusion : seules les 300 premières sont suivies.', info: true });
  [rd, ra].forEach((rep) => {
    if (erreurDe(rep)) { erreurs.push({ chaine: c.nom, msg: 'Lives : ' + erreurDe(rep), info: true }); return; }
    rep.forEach((r) => (r.items || []).forEach((b) => lives.push({ b, chaine: c })));
  });
});

// ---------- Clés de diffusion (onglet CLÉS DE DIFFUSION) ----------
const clesParId = new Map(clesSheet.map((k) => [k.STREAM_ID, k]));
const cles = [];
streams.forEach(({ s, chaine }, id) => {
  const k = clesParId.get(id);
  const recu = s.status && s.status.streamStatus === 'active';
  if (k) {
    cles.push({ ...k, CHAINE: chaine.nom, NOM_CLE: s.snippet.title, VU_LE: recu ? MAJ : (k.VU_LE || '') });
  } else {
    const nouvelle = { CHAINE: chaine.nom, STREAM_ID: id, NOM_CLE: s.snippet.title, EQUIPES: nomEquipe(s.snippet.title), ACTIF: 'OUI', AJOUTEE_LE: MAJ, VU_LE: recu ? MAJ : '', NOTE: 'Nouvelle clé : vérifier le nom dans EQUIPES' };
    cles.push(nouvelle);
    clesParId.set(id, nouvelle);
  }
});

// Clés utilisables pour un sport donné
// Une même équipe peut avoir plusieurs clés : on garde celle qui reçoit un flux, sinon celle qui a un live programmé
function trouverCle(equipe, fam) {
  let cands = [];
  clesParId.forEach((k, id) => {
    if (norm(k.ACTIF) === 'NON') return;
    const st = streams.get(id);
    const chaine = st ? st.chaine : CHAINES.find((c) => c.nom === k.CHAINE);
    if (chaine && chaine.sport && chaine.sport !== fam) return;
    const noms = String(k.EQUIPES || k.NOM_CLE || '').split(/\s*\|\s*/).filter(Boolean);
    if (/^RTMP Stream\s*\|/i.test(k.EQUIPES || k.NOM_CLE || '')) noms.splice(0, noms.length, nomEquipe(k.EQUIPES || k.NOM_CLE));
    noms.forEach((n) => {
      const r = ressemblance(equipe, n);
      if (r < SEUIL_APPROX) return;
      if (!cands.length || r > cands[0].score) cands = [{ k, id, score: r }];
      else if (r === cands[0].score && !cands.some((c) => c.id === id)) cands.push({ k, id, score: r });
    });
  });
  if (cands.length < 2) return cands[0] || null;
  const actif = (c) => { const st = streams.get(c.id); return st && st.s.status && st.s.status.streamStatus === 'active'; };
  const liee = (c) => lives.some((l) => l.b.contentDetails && l.b.contentDetails.boundStreamId === c.id);
  const choix = cands.find(actif) || cands.find(liee) || cands.find((c) => streams.has(c.id)) || cands[0];
  choix.ids = cands.map((c) => c.id);
  return choix;
}

// ---------- Traductions ----------
const RECEPTION = { active: 'Reçu', inactive: 'Aucun', ready: 'Prête (rien reçu)', created: 'Créée', error: 'Erreur' };
const QUALITE = { good: 'Bonne', ok: 'Correcte', bad: 'Mauvaise', noData: 'Pas de données', revoked: 'Clé révoquée' };
const CYCLE = { live: 'En direct', liveStarting: 'Démarrage', testing: 'Test', testStarting: 'Test', ready: 'Prêt', created: 'Programmé', complete: 'Terminé', revoked: 'Supprimé' };

function livesDe(streamId, debut) {
  const liste = lives.filter((l) => l.b.contentDetails && l.b.contentDetails.boundStreamId === streamId);
  const enDirect = liste.find((l) => /^(live|liveStarting|testing|testStarting)$/.test(l.b.status.lifeCycleStatus));
  const aVenir = liste.filter((l) => !enDirect || l !== enDirect)
    .filter((l) => /^(ready|created)$/.test(l.b.status.lifeCycleStatus))
    .sort((a, b) => Math.abs(new Date(a.b.snippet.scheduledStartTime) - debut) - Math.abs(new Date(b.b.snippet.scheduledStartTime) - debut))[0];
  return { enDirect, aVenir };
}

// ---------- Matchs du jour ----------
const utilisees = new Set();
const matchs = planning
  .filter((m) => String(m.DATE || '').trim() === aujourdhui)
  .filter((m) => !/ANNUL|REPORT/.test(norm(m.STATUT)))
  .filter((m) => !CHAMPIONNATS_IGNORES.includes(norm(m.CHAMPIONNAT)));

matchs.forEach((m) => {
  const dom = m['DOMICILE'] || '', ext = m['EXTÉRIEUR'] || m['EXTERIEUR'] || '';
  const fam = famille(m.SPORT);
  const debut = dateParis(m.DATE, m.HEURE);
  const prev = prevParMatch.get(m.ID_MATCH) || {};
  const ligne = {
    MAJ, DATE: aujourdhui, HEURE: m.HEURE || '', SPORT: m.SPORT || '', CHAMPIONNAT: m.CHAMPIONNAT || '',
    DOMICILE: dom, EXTERIEUR: ext, ID_MATCH: m.ID_MATCH || '', ETAT: '', DETAIL: '',
    CHAINE: '', NOM_CLE: '', STREAM_ID: '', RECEPTION: '', QUALITE: '', PROBLEMES: '', LIVE_YOUTUBE: '',
    VIDEO_ID: prev.VIDEO_ID || '', SPECTATEURS: '', DEBUT_REEL: prev.DEBUT_REEL || '',
    PREMIER_SIGNAL: prev.PREMIER_SIGNAL || '', DERNIER_SIGNAL: prev.DERNIER_SIGNAL || '',
    COUPURES: +prev.COUPURES || 0, LIEN_DPLUS: m.URL || ''
  };
  const notes = [];

  // 1) Quelle clé ? D'abord l'équipe à domicile, sinon l'équipe à l'extérieur
  let trouve = trouverCle(dom, fam);
  if (!trouve) { trouve = trouverCle(ext, fam); if (trouve) notes.push("Clé de l'équipe à l'extérieur"); }
  if (!trouve) {
    ligne.ETAT = 'SANS_CLE';
    ligne.DETAIL = "Aucune clé de diffusion associée à cette équipe : ajoute son nom dans la colonne EQUIPES de l'onglet CLÉS DE DIFFUSION.";
    flux.push(ligne); return;
  }
  if (trouve.score < 1) notes.push(`Rapprochement approximatif avec « ${trouve.k.EQUIPES || trouve.k.NOM_CLE} » : à confirmer dans EQUIPES`);
  if (utilisees.has(trouve.id)) notes.push('Cette clé sert aussi à un autre match aujourd\'hui');
  (trouve.ids || [trouve.id]).forEach((i) => utilisees.add(i));
  ligne.CHAINE = trouve.k.CHAINE; ligne.NOM_CLE = trouve.k.NOM_CLE; ligne.STREAM_ID = trouve.id;

  const st = streams.get(trouve.id);
  if (!st) {
    const errChaine = erreurs.find((e) => e.chaine === trouve.k.CHAINE && !e.info);
    ligne.ETAT = errChaine ? 'ERREUR_API' : 'SANS_CLE';
    ligne.DETAIL = errChaine ? `YouTube n'a pas répondu pour ${errChaine.chaine} : ${errChaine.msg}` : "Cette clé n'existe plus sur YouTube.";
    flux.push(ligne); return;
  }

  // 2) Réception et qualité
  const s = st.s.status || {};
  const sante = s.healthStatus || {};
  const recu = s.streamStatus === 'active';
  ligne.RECEPTION = RECEPTION[s.streamStatus] || s.streamStatus || '';
  ligne.QUALITE = recu ? (QUALITE[sante.status] || sante.status || '') : '';
  const problemes = (sante.configurationIssues || []).filter((i) => i.severity !== 'info');
  ligne.PROBLEMES = recu ? problemes.map((i) => i.description || i.reason).join(' · ') : '';
  const degrade = recu && (sante.status === 'bad' || problemes.some((i) => i.severity === 'error'));

  // 3) Live YouTube lié à la clé
  const { enDirect, aVenir } = livesDe(trouve.id, debut || maintenant);
  const live = enDirect || aVenir;
  if (live) {
    ligne.LIVE_YOUTUBE = CYCLE[live.b.status.lifeCycleStatus] || live.b.status.lifeCycleStatus;
    ligne.VIDEO_ID = live.b.id;
    if (live.b.snippet.actualStartTime) ligne.DEBUT_REEL = horo(new Date(live.b.snippet.actualStartTime));
  } else if (ligne.VIDEO_ID) {
    ligne.LIVE_YOUTUBE = 'Terminé';
  }

  // 4) Historique depuis le passage précédent
  if (recu) {
    if (!ligne.PREMIER_SIGNAL) ligne.PREMIER_SIGNAL = MAJ;
    ligne.DERNIER_SIGNAL = MAJ;
  }
  const minutes = debut ? (maintenant - debut) / 60000 : null;
  const duree = DUREE_MIN[fam] || DUREE_MIN.AUTRE;
  const pendant = minutes !== null && minutes >= -AVANT_MIN && minutes <= duree;
  if (!recu && prev.RECEPTION === 'Reçu' && pendant) ligne.COUPURES += 1;

  // 5) État
  if (recu) {
    if (degrade) { ligne.ETAT = 'DEGRADE'; notes.unshift(`Qualité ${ligne.QUALITE.toLowerCase() || 'dégradée'}${ligne.PROBLEMES ? ' : ' + ligne.PROBLEMES : ''}`); }
    else if (!enDirect && minutes !== null && minutes >= 0) {
      ligne.ETAT = 'SANS_LIVE';
      notes.unshift(aVenir ? `Flux reçu mais le live YouTube n'est pas lancé (${ligne.LIVE_YOUTUBE})` : 'Flux reçu mais aucun live YouTube lié à cette clé : rien n\'est visible en ligne');
    } else ligne.ETAT = 'OK';
    if (!live && minutes !== null && minutes < 0) notes.push('Aucun live YouTube programmé sur cette clé');
  } else if (minutes === null) {
    ligne.ETAT = 'ATTENTE'; notes.push('Heure du match inconnue');
  } else if (minutes < -AVANT_MIN) {
    ligne.ETAT = 'ATTENTE';
    if (!live) notes.push('Aucun live YouTube programmé sur cette clé');
  } else if (minutes <= duree) {
    ligne.ETAT = ligne.PREMIER_SIGNAL ? 'COUPE' : 'ABSENT';
    notes.unshift(ligne.PREMIER_SIGNAL ? `Flux coupé depuis ${ligne.DERNIER_SIGNAL.slice(11)}` : (minutes < 0 ? `Coup d'envoi dans ${Math.round(-minutes)} min et aucun flux` : `Match commencé depuis ${Math.round(minutes)} min et aucun flux`));
  } else {
    ligne.ETAT = ligne.PREMIER_SIGNAL ? 'TERMINE' : 'NON_RECU';
  }
  if (ligne.COUPURES) notes.push(`${ligne.COUPURES} coupure${ligne.COUPURES > 1 ? 's' : ''}`);
  ligne.DETAIL = notes.join(' · ');
  flux.push(ligne);
});

// ---------- Flux reçus hors planning (test, match non programmé…) ----------
streams.forEach(({ s, chaine }, id) => {
  if (utilisees.has(id) || !s.status || s.status.streamStatus !== 'active') return;
  const prev = prevParCle.get(id) || {};
  const { enDirect } = livesDe(id, maintenant);
  const k = clesParId.get(id) || {};
  flux.push({
    MAJ, DATE: aujourdhui, HEURE: '', SPORT: chaine.sport ? chaine.sport.charAt(0) + chaine.sport.slice(1).toLowerCase() : '', CHAMPIONNAT: '',
    DOMICILE: nomEquipe(k.EQUIPES || s.snippet.title), EXTERIEUR: '', ID_MATCH: '', ETAT: 'HORS_PLANNING',
    DETAIL: 'Flux reçu sur une clé qui n\'a pas de match aujourd\'hui dans « à venir D+ »',
    CHAINE: chaine.nom, NOM_CLE: s.snippet.title, STREAM_ID: id,
    RECEPTION: 'Reçu', QUALITE: QUALITE[(s.status.healthStatus || {}).status] || '', PROBLEMES: '',
    LIVE_YOUTUBE: enDirect ? CYCLE[enDirect.b.status.lifeCycleStatus] : '', VIDEO_ID: enDirect ? enDirect.b.id : '',
    SPECTATEURS: '', DEBUT_REEL: enDirect && enDirect.b.snippet.actualStartTime ? horo(new Date(enDirect.b.snippet.actualStartTime)) : '',
    PREMIER_SIGNAL: prev.PREMIER_SIGNAL || MAJ, DERNIER_SIGNAL: MAJ, COUPURES: 0, LIEN_DPLUS: ''
  });
});

// ---------- Erreurs d'API ----------
erreurs.forEach((e) => flux.push({
  MAJ, DATE: aujourdhui, HEURE: '', SPORT: '', CHAMPIONNAT: '', DOMICILE: '', EXTERIEUR: '', ID_MATCH: '',
  ETAT: e.info ? 'INFO' : 'ERREUR_API', DETAIL: e.msg, CHAINE: e.chaine, NOM_CLE: '', STREAM_ID: '', RECEPTION: '',
  QUALITE: '', PROBLEMES: '', LIVE_YOUTUBE: '', VIDEO_ID: '', SPECTATEURS: '', DEBUT_REEL: '',
  PREMIER_SIGNAL: '', DERNIER_SIGNAL: '', COUPURES: '', LIEN_DPLUS: ''
}));

flux.sort((a, b) => (a.HEURE || '99').localeCompare(b.HEURE || '99') || a.DOMICILE.localeCompare(b.DOMICILE, 'fr'));
const videoIds = [...new Set(flux.filter((f) => f.LIVE_YOUTUBE === 'En direct' && f.VIDEO_ID).map((f) => f.VIDEO_ID))].slice(0, 50);

return [{ json: { flux, cles, videoIds, precedent: precedent.map((r) => ({ ID_MATCH: r.ID_MATCH, STREAM_ID: r.STREAM_ID, ETAT: r.ETAT })) } }];

// Ajoute le nombre de spectateurs (si des lives sont en cours) puis sort une ligne par match
const res = $('Analyser les flux').first().json;
const vues = new Map();
try {
  $('Spectateurs').all().forEach((i) => (i.json.items || []).forEach((v) => {
    const d = v.liveStreamingDetails || {};
    vues.set(v.id, d.concurrentViewers ?? '');
  }));
} catch (e) { /* aucun live en cours : nœud Spectateurs non exécuté */ }
// Toujours au moins une ligne : l'onglet est vidé puis réécrit, et le site lit l'heure de la dernière vérification
if (!res.flux.length) {
  const t = new Intl.DateTimeFormat('fr-FR', { timeZone: 'Europe/Paris', dateStyle: 'short', timeStyle: 'short' }).format(new Date()).replace(',', '');
  return [{ json: { MAJ: t, DATE: t.slice(0, 10), ETAT: 'INFO', DETAIL: "Aucun match Delaunay+ aujourd'hui dans « à venir D+ »" } }];
}
return res.flux.map((f) => ({ json: { ...f, SPECTATEURS: vues.has(f.VIDEO_ID) ? String(vues.get(f.VIDEO_ID)) : '' } }));

// Prépare un mail seulement quand un match change d'état (nouveau problème ou retour à la normale)
const PROBLEME = { ABSENT: '🔴 Aucun flux', COUPE: '🔴 Flux coupé', DEGRADE: '🟠 Flux dégradé', SANS_LIVE: '🟠 Live YouTube pas lancé', ERREUR_API: '⚠️ Erreur YouTube' };
const avant = new Map($('Analyser les flux').first().json.precedent.map((p) => [p.ID_MATCH || p.STREAM_ID, p.ETAT]));
const lignes = [];
$input.all().forEach(({ json: f }) => {
  const cle = f.ID_MATCH || f.STREAM_ID;
  if (!cle) return;
  const ancien = avant.get(cle) || '';
  if (f.ETAT === ancien) return;
  const match = f.EXTERIEUR ? `${f.DOMICILE} – ${f.EXTERIEUR}` : f.DOMICILE;
  if (PROBLEME[f.ETAT]) lignes.push(`${PROBLEME[f.ETAT]} — ${f.HEURE} ${match} (${f.CHAINE})${f.DETAIL ? ' : ' + f.DETAIL : ''}`);
  else if (f.ETAT === 'OK' && PROBLEME[ancien]) lignes.push(`🟢 Rétabli — ${f.HEURE} ${match} (${f.CHAINE})`);
});
if (!lignes.length) return [];
const alertes = lignes.filter((l) => !l.startsWith('🟢')).length;
return [{ json: {
  sujet: alertes ? `[Delaunay+] ${alertes} flux à surveiller` : '[Delaunay+] Flux rétablis',
  texte: lignes.join('\n') + '\n\nCentre de suivi : https://valentindelaunayproductions.github.io/Resultats-delaunay-/#flux'
} }];

// Une ligne par clé de diffusion trouvée sur YouTube (ajout des nouvelles, mise à jour des autres)
return $('Analyser les flux').first().json.cles.map((k) => ({ json: {
  CHAINE: k.CHAINE || '', STREAM_ID: k.STREAM_ID, NOM_CLE: k.NOM_CLE || '', EQUIPES: k.EQUIPES || '',
  ACTIF: k.ACTIF || 'OUI', AJOUTEE_LE: k.AJOUTEE_LE || '', VU_LE: k.VU_LE || '', NOTE: k.NOTE || ''
} }));
